#!/usr/bin/env bash
set -euo pipefail

# omp/install.sh — install this repo into omp / oh-my-pi (~/.omp/agent/), the
# counterpart of ../install.sh for opencode. Run via `./install.sh --omp`.
# Idempotent; re-run after pulling or after editing roles.yaml, agents or
# skills/create-harness/SKILL.omp.md.
#
#   skills/<name>       -> $AGENT_DIR/skills/<name>  (symlink; skills with a
#                          SKILL.omp.md are installed as a real-dir COPY whose
#                          SKILL.md is SKILL.omp.md)
#   omp/agents/*.md     -> $AGENT_DIR/agents/        (generated by build.py)
#   omp/RULES.md        -> $AGENT_DIR/RULES.md       (generated by build.py)
#   omp/AGENTS.md       -> $AGENT_DIR/AGENTS.md      (generated by build.py)
#   omp/config.fragment.yml merged into $AGENT_DIR/config.yml (not linked: omp
#                          writes that file itself; see merge_config.py)
#   omp/extension      added to the `extensions:` list of $AGENT_DIR/config.yml
#                          (policy extension: per-agent MCP scoping + spawn
#                          guard; deliberately not symlinked into extensions/,
#                          which would load it twice)
#   omp/mcp.json        merged into $AGENT_DIR/mcp.json (not linked: omp writes
#                          that file via `/mcp add`; servers are added by name,
#                          existing entries are never changed; see mcp.py)
#
# OMP_SKIP_BUILD=1 skips the `python3 omp/build.py` regeneration (tests set it so
# a test run never rewrites the working tree; freshness is checked separately).
#
# AGENT_DIR defaults to ~/.omp/agent; PI_CODING_AGENT_DIR relocates it (omp
# honours the same variable).

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
AGENT_DIR="${PI_CODING_AGENT_DIR:-$HOME/.omp/agent}"
TS="$(date +%Y%m%d-%H%M%S)"
COPY_MARKER=".harness-omp-copy"

source "$REPO/lib/link.sh"

# install_skill_copy SOURCE TARGET — real directory copy of a skill whose
# SKILL.omp.md becomes SKILL.md. A previous copy of ours (marker file) or a
# symlink is removed; any other real dir is backed up.
install_skill_copy() {
    local source="$1" target="$2"
    if [ -L "$target" ]; then
        rm "$target"
    elif [ -d "$target" ] && [ -f "$target/$COPY_MARKER" ]; then
        rm -rf "$target"
    elif [ -e "$target" ]; then
        echo "  Backing up existing $target -> $target.bak-$TS"
        mv "$target" "$target.bak-$TS"
    fi
    mkdir "$target"
    (cd "$source" && tar --exclude=__pycache__ --exclude=SKILL.omp.md -cf - .) | (cd "$target" && tar -xf -)
    cp "$source/SKILL.omp.md" "$target/SKILL.md"
    echo "generated by omp/install.sh from $source (SKILL.omp.md); re-run to refresh" > "$target/$COPY_MARKER"
    echo "  $target (copy of $source, SKILL.omp.md -> SKILL.md)"
}

echo "Installing omp config from $REPO into $AGENT_DIR"
if [ "${OMP_SKIP_BUILD:-}" != "1" ]; then python3 "$REPO/omp/build.py"; fi
echo ""

mkdir -p "$AGENT_DIR/skills" "$AGENT_DIR/agents"

link_count=0
copy_count=0
for skill_path in "$REPO"/skills/*/; do
    skill_path="${skill_path%/}"
    name="$(basename "$skill_path")"
    if [ -f "$skill_path/SKILL.omp.md" ]; then
        install_skill_copy "$skill_path" "$AGENT_DIR/skills/$name"
        copy_count=$((copy_count + 1))
    else
        link "$skill_path" "$AGENT_DIR/skills/$name"
        link_count=$((link_count + 1))
    fi
done

agent_count=0
for agent_file in "$REPO"/omp/agents/*.md; do
    link "$agent_file" "$AGENT_DIR/agents/$(basename "$agent_file")"
    agent_count=$((agent_count + 1))
done

link "$REPO/omp/RULES.md" "$AGENT_DIR/RULES.md"
link "$REPO/omp/AGENTS.md" "$AGENT_DIR/AGENTS.md"

echo ""
python3 "$REPO/omp/mcp.py" merge "$REPO/omp/mcp.json" "$AGENT_DIR/mcp.json"
if [ -z "${GOOGLE_SHEETS_MCP_CLIENT_ID:-}" ] || [ -z "${GOOGLE_SHEETS_MCP_CLIENT_SECRET:-}" ]; then
    echo "  NOTE: google-sheets needs GOOGLE_SHEETS_MCP_CLIENT_ID and GOOGLE_SHEETS_MCP_CLIENT_SECRET exported (see omp/mcp.py); OAuth servers sign in with /mcp reauth <name>."
fi

echo ""
python3 "$REPO/omp/merge_config.py" "$REPO/omp/config.fragment.yml" "$AGENT_DIR/config.yml" --extension-dir "$REPO/omp/extension"

echo ""
echo "Done. Installed:"
echo "  - $link_count skills (symlinks) + $copy_count skills (copies) -> $AGENT_DIR/skills/"
echo "  - $agent_count agents -> $AGENT_DIR/agents/"
echo "  - RULES.md, AGENTS.md -> $AGENT_DIR/"
echo "  - config.yml (incl. extensions: $REPO/omp/extension), mcp.json merged in $AGENT_DIR/"
